"""
SENSEX futures resolution from Dhan's instrument master — STATUS: BLOCKED
until a real header and sample rows are verified.

Nothing here guesses the file format. The parser only runs with an explicit
`InstrumentMapping` that names the real column headers, the real cell values
(exchange, instrument type, underlying) and the real expiry date format. No
mapping is shipped: the user creates one from the verified header
(docs/PHASE5_DATA_CLIENT_DESIGN.md §4). Until then the scanner needs the
futures contract passed explicitly and refuses an expired one.

Selection rule = the existing approved rule in
server/src/instruments/registry.ts `futuresForExpiry`: the nearest futures
contract that expires ON OR AFTER the option expiry. Expired contracts
(expiry before today) are never eligible.
"""

from __future__ import annotations

import csv
import io
import json
from dataclasses import dataclass, field
from datetime import date, datetime

REQUIRED_COLUMNS = ("exchange", "security_id", "instrument", "underlying", "expiry", "lot_size")
REQUIRED_VALUES = ("exchange", "instrument", "underlying")


class InstrumentResolutionError(Exception):
    code = "INSTRUMENT"


class MappingMissingError(InstrumentResolutionError):
    code = "BLOCKED_NO_VERIFIED_MAPPING"


class MappingMismatchError(InstrumentResolutionError):
    code = "MAPPING_HEADER_MISMATCH"


class NoEligibleContractError(InstrumentResolutionError):
    code = "NO_ELIGIBLE_FUTURE"


class DuplicateContractError(InstrumentResolutionError):
    code = "DUPLICATE_FUTURE"


@dataclass(frozen=True)
class InstrumentMapping:
    columns: dict            # logical name -> real header text
    values: dict             # logical name -> real cell value to match
    expiry_format: str       # datetime.strptime format of the real expiry cell
    verified_from: str = ""  # where the header was verified (who/when/sample)

    @staticmethod
    def from_dict(raw: dict) -> "InstrumentMapping":
        """Validate a mapping already read from a VERIFIED file (sensex.localio.load_mapping reads it)."""
        m = InstrumentMapping(raw.get("columns") or {}, raw.get("values") or {}, raw.get("expiry_format") or "",
                              raw.get("verified_from") or "")
        missing = [c for c in REQUIRED_COLUMNS if not m.columns.get(c)] + \
                  ["values." + v for v in REQUIRED_VALUES if not m.values.get(v)] + \
                  (["expiry_format"] if not m.expiry_format else [])
        if missing:
            raise MappingMissingError("Instrument mapping incomplete: %s" % ", ".join(missing))
        if not m.verified_from:
            raise MappingMissingError("Instrument mapping must state 'verified_from' (the real sample it was built from).")
        return m


@dataclass(frozen=True)
class FuturesContract:
    security_id: str
    expiry: date
    lot_size: int | None
    exchange: str
    raw_expiry: str


@dataclass
class ParseReport:
    rows_total: int = 0
    rows_matching: int = 0
    malformed_expiry: int = 0
    malformed_lot: int = 0
    malformed_id: int = 0
    notes: list = field(default_factory=list)


def parse_futures(csv_text: str, mapping: InstrumentMapping):
    """Return (contracts, report) for rows matching the mapping's exchange,
    instrument and underlying values. Malformed rows are counted, not guessed."""
    reader = csv.reader(io.StringIO(csv_text))
    try:
        header = [h.strip() for h in next(reader)]
    except StopIteration:
        raise MappingMismatchError("Instrument master is empty") from None
    idx = {}
    for logical in REQUIRED_COLUMNS:
        real = mapping.columns[logical]
        if real not in header:
            raise MappingMismatchError("Column %r (for %s) is not in the header; the format changed or the "
                                       "mapping is wrong. Header starts: %s" % (real, logical, header[:12]))
        idx[logical] = header.index(real)
    want = {k: str(mapping.values[k]).strip().upper() for k in REQUIRED_VALUES}
    rep = ParseReport()
    out = []
    for row in reader:
        if not row or not any(c.strip() for c in row):
            continue
        rep.rows_total += 1
        cell = lambda k: row[idx[k]].strip() if idx[k] < len(row) else ""  # noqa: E731
        if any(cell(k).upper() != want[k] for k in REQUIRED_VALUES):
            continue
        rep.rows_matching += 1
        sid = cell("security_id")
        if not sid.isdigit():
            rep.malformed_id += 1
            continue
        raw_exp = cell("expiry")
        try:
            exp = datetime.strptime(raw_exp, mapping.expiry_format).date()
        except ValueError:
            rep.malformed_expiry += 1
            continue
        lot_txt = cell("lot_size")
        lot = None
        try:
            v = float(lot_txt)
            if v > 0 and v == int(v):
                lot = int(v)
            else:
                rep.malformed_lot += 1
        except ValueError:
            rep.malformed_lot += 1
        out.append(FuturesContract(sid, exp, lot, cell("exchange"), raw_exp))
    return out, rep


def select_future(contracts, option_expiry: date, today: date) -> FuturesContract:
    """Nearest contract with expiry >= option_expiry (and not before today)."""
    eligible = [c for c in contracts if c.expiry >= option_expiry and c.expiry >= today]
    if not eligible:
        raise NoEligibleContractError(
            "No unexpired futures contract expires on or after %s (candidates: %s)"
            % (option_expiry, sorted({str(c.expiry) for c in contracts})[:6]))
    nearest = min(c.expiry for c in eligible)
    at = {c.security_id: c for c in eligible if c.expiry == nearest}
    if len(at) > 1:
        raise DuplicateContractError("Ambiguous: %d different security ids expire on %s (%s); refusing to pick one."
                                     % (len(at), nearest, sorted(at)))
    return next(iter(at.values()))


def explicit_future(security_id: str, expiry: str, today: date, option_expiry: date) -> FuturesContract:
    """The contract the user passed on the command line, validated the same way."""
    if not str(security_id).strip().isdigit():
        raise InstrumentResolutionError("futures security id must be digits")
    exp = date.fromisoformat(expiry)
    c = FuturesContract(str(security_id).strip(), exp, None, "BSE", expiry)
    return select_future([c], option_expiry, today)
